mapper.select:
SELECT id, user_id, client_ip, last_used_at, created_at
FROM auth_customer_trusted_login_ip
WHERE user_id = #{userId}
  AND client_ip = #{clientIp}
LIMIT 1

mapper.insert:
INSERT INTO auth_customer_trusted_login_ip (
    user_id, client_ip, last_used_at, created_at
)
VALUES (
    #{userId}, #{clientIp}, #{lastUsedAt}, #{lastUsedAt}
)
ON DUPLICATE KEY UPDATE
    last_used_at = VALUES(last_used_at)

mapper.select:
SELECT COUNT(*)
FROM auth_customer_trusted_login_ip
WHERE user_id = #{userId}

mapper.delete:
DELETE FROM auth_customer_trusted_login_ip
WHERE id IN (
    SELECT id FROM (
        SELECT id
        FROM auth_customer_trusted_login_ip
        WHERE user_id = #{userId}
        ORDER BY last_used_at ASC, id ASC
        LIMIT #{limit}
    ) oldest
)
